from pathlib import Path
import hashlib,json,re,tarfile,subprocess
root=Path.cwd(); ev=root/'evidence/s02-candidate-a-completion/a3/task2';src=root/'.superpowers/sdd/a3-task2-receipts'
h=lambda b:hashlib.sha256(b).hexdigest()
errors=[]; entries=[]
def check(ok,label):
 if not ok:errors.append(label)
with tarfile.open(ev/'author-evidence.tar.gz','r:gz') as t:
 for member in t:
  if member.isfile():
   raw=t.extractfile(member).read();check((root/member.name).read_bytes()==raw,'archive-original:'+member.name)
   entries.append({'path':member.name,'bytes':len(raw),'sha256':h(raw)})
closures={}
for stage,test in [('red','funding-test.json'),('green','task2-tests.json')]:
 r=json.loads((src/stage/test).read_text());closures[stage]=r['sourceClosure']
 check(r['exitCode']==(1 if stage=='red' else 0),'terminal:'+stage)
 check(r['chunks'][-1].get('exit_code')==r['exitCode'],'raw-terminal:'+stage)
 output=''.join(x.get('output','')for x in r['chunks'])
 if stage=='red':check('QNT508' in output and '1 failed' in output,'behavioral-red')
 else:check(re.findall(r'ok (\w+Test) passed',output)==['literalFidelityTest','authorityTimeZeroTest','fundingTest','dispositionMatrixTest','replayTest'] and '5 passing' in output,'complete-green-inventory')
 for f in r['sourceClosure']:
  raw=(src/stage/'source'/f['path']).read_bytes();check(h(raw)==f['sha256'],'snapshot:'+stage+':'+f['path'])
  if stage=='green':check((root/f['path']).read_bytes()==raw,'live:'+f['path'])
  if not Path(f['path']).name.startswith('candidate_a_authority_swap'):check(subprocess.check_output(['git','show','d14cfea98a1c9213e5ef5f12c1a088f4e966083d:'+f['path']])==raw,'frozen:'+f['path'])
 check(len(r['sourceClosure'])==15,'closure-size:'+stage)
 for part in [r['tool'],r['tool']['backend']]:check(h(Path(part['path']).read_bytes())==part['sha256'],'tool:'+part['path'])
 for name in ['typecheck']:
  tc=json.loads((src/stage/(name+'.json')).read_text());check(tc['exitCode']==0 and tc['chunks'][-1].get('exit_code')==0,'typecheck:'+stage+name)
  check({x['path']:x['sha256'] for x in tc['sourceClosure']}=={x['path']:x['sha256'] for x in r['sourceClosure']},'typecheck-closure:'+stage+name)
fixture='specs/quint/s02/candidate_a_authority_swap.qnt'
red=(src/'red/source'/fixture).read_text();green=(src/'green/source'/fixture).read_text()
check(red.replace('| CommitS(id) => state','| CommitS(id) => applyCommit(state, id)')==green,'exact-red-correction')
check({x['path']:x['sha256'] for x in closures['red'] if x['path']!=fixture}=={x['path']:x['sha256'] for x in closures['green'] if x['path']!=fixture},'only-fixture-changed')
review=(ev/'independent-review.md').read_text()
check(all(x in review for x in ['6a3d32f147653196cd83fafb3ccf64d118b8424acc00948947d7484a88f9909d','d0efb0823c4bed3c15b5d89ce9ef61dab8d5c2123d928da6a71e3c04edc724fc','approved']),'review-pins')
print(json.dumps({'status':'local-A3-Task2-accepted' if not errors else 'open-a3-task2','errors':errors,'archive':{'sha256':h((ev/'author-evidence.tar.gz').read_bytes()),'members':entries},'greenSourceClosure':closures['green'],'limits':['Author-executed runtime independently source/receipt audited; root did not duplicate tests','Actual finite guarded prefixes, no stateful sampling, Council, model checking or full A3 acceptance']},indent=2))
raise SystemExit(bool(errors))
PY

